# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
L=[['拉丁 flectere；分词 flexus','弯曲、使转向']]
R=L+[['拉丁 re- + flectere → reflectere','向后 + 弯转 → 折回'],['古法语 reflecter → 英语 reflect','反射；映出；回想、反思']]
RN=L+[['拉丁 reflectere → 晚期拉丁 reflexio','折回 → 折回这一行为'],['法语 reflexion／refleccion → 英语 reflection','反射、映像、思考；ct 拼写受 reflect 等影响']]
def H(chain,label,meaning):return chain+[[label,meaning]]
WA=[
E('reflect','/rɪˈflekt/','反射；映出、反映；认真思考','光碰到镜面折回来；脑中的注意力，也可以折回到刚发生的事上。','拉丁 re-“向后” + flectere“弯、转向”。现代 reflect 是整词借入，不能把 re- 一律译成“再做一次”。',R,'The lake reflects the sky 是湖面映出天空；results reflect effort 是结果反映投入。reflect on a mistake 则把注意力转回那次错误，想想原因。最后这一义不是照镜子，而是把同一种“转回来”的画面用于思考。','reflect light；reflect a change；reflect on an experience；reflect badly on someone（给某人的形象带来负面影响）。','reflect 让光折回；refract 让光在进入另一介质时偏折。reflect on 强调回顾思考，remember 只需记得。',('The glass reflects the trees outside.','玻璃上映出外面的树。'),('Take a moment to reflect on what you learned.','花一点时间想想你学到了什么。'),('The survey results reflect a change in public opinion.','调查结果反映了公众看法的变化。'),sources=['https://www.etymonline.com/word/reflect','https://en.wiktionary.org/wiki/reflect']),
E('reflection','/rɪˈflekʃən/','倒影、映像；反射；反思、考虑','看见水中的自己，或把一件事放回脑中，重新看一遍。','现代可对应 reflect + -ion；历史上名词由晚期拉丁 reflexio 经法语借入，是同源名词支线。',RN,'a reflection in the mirror 是镜中的像；after reflection 是经过考虑之后。说 something is a reflection of a society，是把社会想成被照出的对象：从这个现象能看出社会的一部分。反思义常不可数，具体的想法也可用复数 reflections。','see your reflection；on reflection（再想想之后）；a reflection of；reflections on life。','reflection 可以是看见的像，也可以是思考过程；reflex 常指无需有意识决定的反应，不能因都译过“反射”就互换。',('Her reflection disappeared as the water began to ripple.','水面泛起波纹，她的倒影便消失了。'),('On reflection, we decided to delay the launch.','再三考虑后，我们决定推迟发布。'),sources=['https://www.etymonline.com/word/reflection','https://en.wiktionary.org/wiki/reflection']),
E('reflective','/rɪˈflektɪv/','反光的；沉思的；能反映某事的','一面把光送回来；另一面把心思收回来，慢慢想清楚。','reflect + -ive，把动作变成一种性质或状态。',H(R,'英语 reflect + -ive → reflective','反射、思考 → 反光的、沉思的'),'reflective clothing 会把照来的光反射出去，让人更容易看见；a reflective mood 是安静回想、认真琢磨的心情。be reflective of a trend 则是“能反映某种趋势”，不是说趋势正在思考。','reflective material；a reflective mood；reflective writing；be reflective of。','reflective 常表示认真思考；reflexive 在反应义中却常表示自动、未经思考。两者只差几个字母，意思可能正好不同。',('The cyclist wore a jacket with reflective strips.','骑车的人穿着带反光条的外套。'),('She became quiet and reflective after the meeting.','会后她安静下来，陷入思考。'),sources=['https://www.etymonline.com/word/reflective','https://en.wiktionary.org/wiki/reflective']),
E('reflected','/rɪˈflektɪd/','反射的；体现出来的；reflect 的过去式、过去分词','光已经从表面折回来，或某件事已经在结果里留下了影子。','reflect + -ed；词尾 t 后的 -ed 读 /ɪd/。',H(R,'英语 reflect → reflected','反射、反映 → 反射了、被反映的'),'reflected light 是从别处照来、经过表面再进入眼睛的光。be reflected in the figures 表示变化能从数字中看出来。bask in reflected glory 是借别人的成就沾光：光来自别人，自己站在旁边也亮了一点。','reflected light；be reflected in；reflected glory。','reflective 说材料有反光性质；reflected light 说这束光已经被反射。',('The room was lit mainly by reflected light.','房间主要靠反射过来的光照亮。'),('The improvement is reflected in the latest figures.','最新数字体现了这一改善。'),sources=['https://en.wiktionary.org/wiki/reflected','https://www.merriam-webster.com/dictionary/reflect']),
E('reflecting','/rɪˈflektɪŋ/','正在反思、反射；用来反射的','注意力还在往回看，或光正被镜面转向。','reflect + -ing，可作动词形式，也可修饰具有反射作用的东西。',H(R,'英语 reflect → reflecting','反射、思考 → 正在做这件事或有这种作用'),'She is reflecting on the interview 说她正在回想面试。a reflecting telescope 利用镜面收集、反射光线；这里 reflecting 是说明设备怎样工作，不是望远镜在沉思。结合后面的名词或介词判断是哪一支意思。','reflecting on；a reflecting surface；a reflecting telescope。','reflecting 描述正在进行的动作或反射用途；reflective 也可强调人的沉思状态和材料的反光性质。',('He sat by the window, reflecting on the conversation.','他坐在窗边，回想着那次谈话。'),('The observatory installed a new reflecting telescope.','天文台安装了一台新的反射式望远镜。'),sources=['https://en.wiktionary.org/wiki/reflecting','https://science.nasa.gov/universe/telescopes-101/']),
E('reflectively','/rɪˈflektɪvli/','若有所思地；经过反思地','说话之前，先让这句话在心里转一圈。','reflective + -ly，把“沉思的”变成做事的方式。',H(R,'英语 reflect → reflective → reflectively','思考 → 沉思的 → 若有所思地'),'someone said reflectively 常描写人物一边想一边慢慢说。write reflectively 则要求写出自己怎样理解经历，而不只是按顺序列出发生了什么。它强调思考的姿态和过程，不保证结论一定正确。','say reflectively；write reflectively；look back reflectively。','reflectively 说经过思考或沉思；reflexively 常说下意识地，两词不能混写。',('“We could have handled that better,” she said reflectively.','“那件事我们本来可以处理得更好。”她若有所思地说。'),('Students are asked to write reflectively about their placements.','学生需要结合实习经历写出自己的反思。'),sources=['https://dictionary.cambridge.org/us/dictionary/english/reflectively']),
E('unreflective','/ˌʌnrɪˈflektɪv/','缺少反思的；不假思索的；不能反映实际情况的','某种习惯一路向前跑，却没有停下来问一句“为什么”。','un-“不” + reflective“会反思的”。',H(R,'英语 reflective → unreflective','会思考、反省的 → 缺少反省的'),'unreflective acceptance 是没仔细想就接受；an unreflective habit 是习惯如此，却少有审视。这个词批评的是缺少回头检查的过程，不等于这个人没有智力，也不一定说明其决定最终错误。另一用法 unreflective of 表示“不能体现实际情况”，接的是 reflect“反映”这一义。','unreflective acceptance；unreflective habits；an unreflective response。','unreflective 指缺少反思；uninformed 指信息不足。有信息的人也可能未经反思便接受某种观点。',('The essay challenges our unreflective acceptance of the rule.','文章质疑我们对这条规则不加思考的接受。'),('An unreflective habit can survive long after its purpose has disappeared.','一种未经反思的习惯，即使原来的目的已经消失，也可能一直延续。'),('The sample was unreflective of the wider population.','这个样本不能反映更广泛人群的实际情况。'),sources=['https://www.merriam-webster.com/dictionary/unreflective','https://dictionary.cambridge.org/us/dictionary/english/unreflective']),
E('reflector','英 /rɪˈflektə/；美 /rɪˈflektər/','反射器；反光板；反射式望远镜','接住照来的光，再把光送到需要的方向。','reflect + -or；这里 -or 指承担该作用的物件。',H(R,'英语 reflect + -or → reflector','反射 → 反射光等的装置'),'自行车上的 reflector 借汽车灯的光让自己显眼；摄影师的 reflector 把现有光线补到脸上。它通常不自己发光。天文学中 reflector 也可简称反射式望远镜，因为主要集光元件是镜面。','a bicycle reflector；a silver reflector；a telescope reflector。','reflector 反射已有的光；light source 产生光。一个装置里可以同时有两者。',('The photographer placed a reflector beside the model.','摄影师把反光板放在模特旁边。'),('The bicycle has a red reflector at the back.','自行车后方装有一个红色反光片。'),sources=['https://en.wiktionary.org/wiki/reflector','https://www.merriam-webster.com/dictionary/reflector']),
E('reflectance','/rɪˈflektəns/','反射率〔光学〕','照到表面的光有多少，返回的又有多少：把两者放到同一把尺子上比较。','reflect + -ance，形成表示反射特性的名词。',H(R,'英语 reflect + -ance → reflectance','反射 → 反射通量与入射通量的比值'),'若同一规定条件下入射光通量是100份，反射出去80份，反射率就是0.8。比较时要看波长、入射角和收集反射光的方式。眼睛觉得“很亮”并不是一个完整的 reflectance 测量结果。','surface reflectance；spectral reflectance；measure reflectance。','reflectance 是规定条件下的比例；reflected power 是实际反射了多少功率。比例相同，入射光更强时反射功率仍会更大。',('The coating has high reflectance in the visible range.','这种涂层在可见光范围内有较高的反射率。'),('The team measured reflectance at several wavelengths.','团队测量了几个不同波长下的反射率。'),sources=['https://en.wiktionary.org/wiki/reflectance','https://tsapps.nist.gov/publication/get_pdf.cfm?pub_id=956799']),
E('reflectivity','/ˌriːflekˈtɪvɪti/','反射能力；反射性','表面有多善于把照来的光送回来。','reflective + -ity，将“具有反射性”说成一种性质。',H(R,'英语 reflective → reflectivity','反射的 → 反射性、反射能力'),'a surface’s reflectivity 常谈材料或表面的反射表现，粗糙度、涂层和波长等都可能影响它。在专业文献里要看作者的具体定义；有时它和 reflectance 接近，有时用于更特定的材料性质。不要脱离上下文强行规定二者永远同义或永远不同。','high reflectivity；surface reflectivity；the reflectivity of a coating。','reflectivity 的词形来自 reflective；reflexivity 的词形来自 reflexive，后者常谈自指或研究中的反身性。',('The coating increases the mirror’s reflectivity.','这种涂层提高了镜面的反射能力。'),('Dust can change the reflectivity of a surface.','灰尘可能改变表面的反射特性。'),sources=['https://en.wiktionary.org/wiki/reflectivity','https://www.collinsdictionary.com/dictionary/english/reflectivity']),
]
